contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs matching C.transfer: from, caddress, array of tos and values
    // The test invokes c.transfer and records whether it reverted. The invariant asserted:
    // If the call did not revert, it must have returned true.
    // (This captures that transfer reports success only when all internal calls succeeded.)
    function run(address from, address caddress, address[] calldata _tos, uint[] calldata v) public payable {
        require(_tos.length == v.length || _tos.length == 0 ? true : true);
        // Attempt the call and capture whether it reverted and the returned boolean when it didn't.
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: if the call did not revert, it must return true.
        // This asserts that successful execution implies a true return value.
        assert(reverted || ret);
    }

    receive() external payable {}
}

